components.css:
.brick-onboarding{display:grid;gap:14px;padding:18px;border:1px solid var(--home-primary-border);border-radius:var(--home-radius-sm,8px);background:var(--home-progress-card-bg);color:var(--home-text)}
    .brick-onboarding *{box-sizing:border-box}
    .brick-onboarding>span{color:var(--home-primary);font-size:12px;font-weight:900}
    .brick-onboarding>strong{font-size:22px;letter-spacing:0}
    .brick-onboarding .onboarding-progress-steps{display:grid;grid-template-columns:minmax(260px,1.18fr) repeat(2,minmax(0,1fr));gap:10px;margin:0;padding:0;list-style:none}
    .brick-onboarding .onboarding-progress-steps li{position:relative;display:grid;grid-template-columns:auto 1fr auto;gap:8px 10px;align-items:end;min-height:132px;padding:14px;border:1px solid var(--home-primary-border);border-radius:var(--home-radius-sm,8px);background:var(--home-card-bg);box-shadow:0 12px 28px color-mix(in srgb,var(--home-primary) 10%,transparent)}
    .brick-onboarding .onboarding-progress-steps li:first-child{min-height:176px;background:var(--home-primary-surface)}
    .brick-onboarding .onboarding-progress-steps i{width:42px;height:42px;display:grid;place-items:center;border-radius:var(--home-radius-sm,8px);background:var(--home-button-bg);color:var(--home-button-text);font-style:normal;font-weight:950}
    .brick-onboarding .onboarding-progress-steps b{align-self:start;padding:4px 8px;border-radius:999px;background:var(--home-primary-faint);color:var(--home-primary);font-size:11px}
    .brick-onboarding .onboarding-progress-steps span{color:var(--home-text);font-size:15px;font-weight:950}
    .brick-onboarding .onboarding-progress-steps small{grid-column:2;color:var(--home-text-muted);font-size:11px;font-weight:800}
    .brick-onboarding .onboarding-progress-steps .active{border-color:var(--home-primary-border-strong);background:var(--home-primary-soft);box-shadow:0 14px 32px color-mix(in srgb,var(--home-primary) 14%,transparent)}
    @media(max-width:720px){.brick-onboarding .onboarding-progress-steps{grid-template-columns:1fr}.brick-onboarding .onboarding-progress-steps li:first-child{min-height:130px}}
